import struct

def analyze(path):
    with open(path,'rb') as f:
        data = f.read()
    assert data[16:24] == b'\x00\x00\x00\x10\x00\x00\x00\x06\x00\x00\x00', "unexpected header"
    w = int.from_bytes(data[16:20],'big')
    h = int.from_bytes(data[20:24],'big')
    ihdr_len = 24 + struct.unpack('>I', data[26:30])[0]
    raw = data[ihdr_len:]
    stride = w*3
    buf = bytearray()
    p = 0
    for y in range(h):
        fb = raw[p]; p+=1
        for x in range(w):
            for c in range(3):
                v = raw[p]; p+=1
                if fb==0: buf.append(v)
                elif fb==1: buf.append(v+128)
                elif fb==2: buf.append(256-v)
                elif fb==3: buf.append(-v)
                elif fb==4:
                    prev = buf[-stride:] if stride else b''
                    buf.append(v+prev[c])
                elif fb==5:
                    prev = buf[-stride:] if stride else b''
                    buf.append(v-prev[c-stride])
                elif fb==6:
                    up = buf[-stride*3:] if stride*3 <= len(buf) else b''
                    up = up[-stride*3:]
                    left = buf[-stride:] if stride else b''
                    upl = up[-stride*3:] if stride*3 else b''
                    upl = upl[-stride*3:]
                    buf.append(v+left[c]-up[c]-upl[c-stride]+buf[-1])
    total = w*h*3
    nonwhite = 0
    for i in range(0, total, 3):
        r,g,b = buf[i], buf[i+1], buf[i+2]
        if not (r>240 and g>240 and b>240):
            nonwhite += 1
    return w,h,nonwhite

for name in ['dashboard_r_barras.png','dashboard_r_linea.png']:
    w,h,c = analyze(name)
    print(f"{name}: {w}x{h}px, colored pixels = {c} ({100*c/(w*h):.1f}%)")
